import { test, expect } from '@playwright/test';

test.describe('Modal Dialog Animation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-page');
  });

  test('should open modal with correct animation when button is clicked', async ({ page }) => {
    // Verify modal is not visible initially
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).not.toBeVisible();

    // Click the open modal button using getByRole
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Wait for modal to appear with animation
    await page.waitForTimeout(500);

    // Verify modal is now visible
    await expect(modal).toBeVisible();

    // Verify modal title is displayed using getByRole
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify modal content is visible using getByText
    const modalContent = page.getByText(/modal content/i);
    await expect(modalContent).toBeVisible();

    // Verify close button is available using getByRole
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();
  });

  test('should close modal with correct animation when close button is clicked', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Wait for modal to appear
    await page.waitForTimeout(500);

    // Verify modal is visible
    const modal = page.locator('[data-testid="modal-dialog"]');
    await expect(modal).toBeVisible();

    // Click the close button using getByRole
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Wait for modal to close with animation
    await page.waitForTimeout(500);

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Verify modal title is no longer visible
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).not.toBeVisible();
  });
});
